CREATE TABLE public.board_members (board_id uuid NOT NULL REFERENCES public.boards(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(board_id,user_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.board_members TO authenticated;
GRANT ALL ON public.board_members TO service_role;
ALTER TABLE public.board_members ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.can_access_board(_board_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT auth.uid() IS NOT NULL AND (EXISTS(SELECT 1 FROM public.boards WHERE id=_board_id AND owner_id=auth.uid()) OR EXISTS(SELECT 1 FROM public.board_members WHERE board_id=_board_id AND user_id=auth.uid())) $$;
CREATE POLICY "board members readable by collaborators" ON public.board_members FOR SELECT TO authenticated USING(public.can_access_board(board_id));
CREATE POLICY "owners manage board members" ON public.board_members FOR ALL TO authenticated USING(public.owns_board(board_id)) WITH CHECK(public.owns_board(board_id));
CREATE TABLE public.board_invites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), board_id uuid NOT NULL REFERENCES public.boards(id) ON DELETE CASCADE, email text NOT NULL, token uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE, expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days', accepted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, DELETE ON public.board_invites TO authenticated;
GRANT ALL ON public.board_invites TO service_role;
ALTER TABLE public.board_invites ENABLE ROW LEVEL SECURITY;
CREATE POLICY "owners manage invitations" ON public.board_invites FOR ALL TO authenticated USING(public.owns_board(board_id)) WITH CHECK(public.owns_board(board_id));
CREATE TABLE public.card_mirrors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), card_id uuid NOT NULL REFERENCES public.cards(id) ON DELETE CASCADE, board_id uuid NOT NULL REFERENCES public.boards(id) ON DELETE CASCADE, list_id uuid NOT NULL REFERENCES public.lists(id) ON DELETE CASCADE, position double precision NOT NULL DEFAULT 0, archived boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.card_mirrors TO authenticated;
GRANT ALL ON public.card_mirrors TO service_role;
ALTER TABLE public.card_mirrors ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.can_access_card(_card_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT auth.uid() IS NOT NULL AND (EXISTS(SELECT 1 FROM public.cards WHERE id=_card_id AND public.can_access_board(board_id)) OR EXISTS(SELECT 1 FROM public.card_mirrors WHERE card_id=_card_id AND NOT archived AND public.can_access_board(board_id))) $$;
CREATE POLICY "collaborators read mirror placements" ON public.card_mirrors FOR SELECT TO authenticated USING(public.can_access_board(board_id));
CREATE POLICY "collaborators update mirror placements" ON public.card_mirrors FOR UPDATE TO authenticated USING(public.can_access_board(board_id)) WITH CHECK(public.can_access_board(board_id));
CREATE POLICY "collaborators delete mirror placements" ON public.card_mirrors FOR DELETE TO authenticated USING(public.can_access_board(board_id));
CREATE POLICY "source owners create mirrors" ON public.card_mirrors FOR INSERT TO authenticated WITH CHECK(public.can_access_board(board_id) AND EXISTS(SELECT 1 FROM public.cards c WHERE c.id=card_id AND public.owns_board(c.board_id)));
CREATE TABLE public.card_members (card_id uuid NOT NULL REFERENCES public.cards(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, PRIMARY KEY(card_id,user_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.card_members TO authenticated;
GRANT ALL ON public.card_members TO service_role;
ALTER TABLE public.card_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY "collaborators manage card assignments" ON public.card_members FOR ALL TO authenticated USING(public.can_access_card(card_id)) WITH CHECK(public.can_access_card(card_id) AND EXISTS(SELECT 1 FROM public.cards c WHERE c.id=card_id AND (EXISTS(SELECT 1 FROM public.boards b WHERE b.id=c.board_id AND b.owner_id=user_id) OR EXISTS(SELECT 1 FROM public.board_members bm WHERE bm.board_id=c.board_id AND bm.user_id=card_members.user_id) OR EXISTS(SELECT 1 FROM public.card_mirrors m JOIN public.boards b ON b.id=m.board_id WHERE m.card_id=c.id AND NOT m.archived AND (b.owner_id=user_id OR EXISTS(SELECT 1 FROM public.board_members bm WHERE bm.board_id=m.board_id AND bm.user_id=card_members.user_id))))));
CREATE POLICY "members read shared boards" ON public.boards FOR SELECT TO authenticated USING(public.can_access_board(id));
DROP POLICY "own lists" ON public.lists;
CREATE POLICY "collaborators manage lists" ON public.lists FOR ALL TO authenticated USING(public.can_access_board(board_id)) WITH CHECK(public.can_access_board(board_id));
DROP POLICY "own cards" ON public.cards;
CREATE POLICY "collaborators read cards" ON public.cards FOR SELECT TO authenticated USING(public.can_access_card(id));
CREATE POLICY "collaborators insert cards" ON public.cards FOR INSERT TO authenticated WITH CHECK(public.can_access_board(board_id));
CREATE POLICY "collaborators update cards" ON public.cards FOR UPDATE TO authenticated USING(public.can_access_card(id)) WITH CHECK(public.can_access_card(id));
CREATE POLICY "source owners delete cards" ON public.cards FOR DELETE TO authenticated USING(public.owns_board(board_id));
DROP POLICY "own yt" ON public.youtube_details;
CREATE POLICY "collaborators manage youtube details" ON public.youtube_details FOR ALL TO authenticated USING(public.can_access_card(card_id)) WITH CHECK(public.can_access_card(card_id));
DROP POLICY "own card_labels" ON public.card_labels;
CREATE POLICY "collaborators manage card labels" ON public.card_labels FOR ALL TO authenticated USING(public.can_access_card(card_id)) WITH CHECK(public.can_access_card(card_id) AND EXISTS(SELECT 1 FROM public.labels l JOIN public.cards c ON c.board_id=l.board_id WHERE c.id=card_id AND l.id=label_id));
DROP POLICY "own labels" ON public.labels;
CREATE POLICY "collaborators read labels" ON public.labels FOR SELECT TO authenticated USING(public.can_access_board(board_id) OR EXISTS(SELECT 1 FROM public.cards c WHERE c.board_id=labels.board_id AND public.can_access_card(c.id)));
CREATE POLICY "board collaborators manage labels" ON public.labels FOR ALL TO authenticated USING(public.can_access_board(board_id)) WITH CHECK(public.can_access_board(board_id));
DROP POLICY "own checklists" ON public.checklists;
CREATE POLICY "collaborators manage checklists" ON public.checklists FOR ALL TO authenticated USING(public.can_access_card(card_id)) WITH CHECK(public.can_access_card(card_id));
DROP POLICY "own items" ON public.checklist_items;
CREATE POLICY "collaborators manage checklist items" ON public.checklist_items FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.checklists cl WHERE cl.id=checklist_id AND public.can_access_card(cl.card_id))) WITH CHECK(EXISTS(SELECT 1 FROM public.checklists cl WHERE cl.id=checklist_id AND public.can_access_card(cl.card_id)));
DROP POLICY "own activity" ON public.card_activity;
CREATE POLICY "collaborators manage activity" ON public.card_activity FOR ALL TO authenticated USING(public.can_access_card(card_id)) WITH CHECK(public.can_access_card(card_id));
CREATE POLICY "read shared card covers" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='card-covers' AND (EXISTS(SELECT 1 FROM public.cards c WHERE c.cover_url=name AND public.can_access_card(c.id)) OR EXISTS(SELECT 1 FROM public.boards b WHERE b.background_image=name AND public.can_access_board(b.id))));
CREATE OR REPLACE FUNCTION public.validate_card_location() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.lists WHERE id=NEW.list_id AND board_id=NEW.board_id) THEN RAISE EXCEPTION 'List does not belong to destination board'; END IF; IF TG_TABLE_NAME='cards' AND TG_OP='UPDATE' AND NEW.board_id<>OLD.board_id AND (NOT public.owns_board(OLD.board_id) OR NOT public.can_access_board(NEW.board_id)) THEN RAISE EXCEPTION 'Only the source board owner can move a card between boards'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_cards_location BEFORE INSERT OR UPDATE OF board_id,list_id ON public.cards FOR EACH ROW EXECUTE FUNCTION public.validate_card_location();
CREATE TRIGGER validate_mirrors_location BEFORE INSERT OR UPDATE OF board_id,list_id ON public.card_mirrors FOR EACH ROW EXECUTE FUNCTION public.validate_card_location();
CREATE OR REPLACE FUNCTION public.board_people(_board_id uuid) RETURNS TABLE(user_id uuid,full_name text,is_owner boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,COALESCE(p.full_name,'Member'),p.id=b.owner_id FROM public.boards b JOIN public.profiles p ON p.id=b.owner_id OR EXISTS(SELECT 1 FROM public.board_members m WHERE m.board_id=b.id AND m.user_id=p.id) WHERE b.id=_board_id AND public.can_access_board(b.id) $$;
CREATE OR REPLACE FUNCTION public.card_people(_card_id uuid) RETURNS TABLE(user_id uuid,full_name text,is_assigned boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT DISTINCT p.id,COALESCE(p.full_name,'Member'),EXISTS(SELECT 1 FROM public.card_members cm WHERE cm.card_id=_card_id AND cm.user_id=p.id) FROM public.profiles p JOIN public.boards b ON p.id=b.owner_id OR EXISTS(SELECT 1 FROM public.board_members bm WHERE bm.board_id=b.id AND bm.user_id=p.id) WHERE public.can_access_card(_card_id) AND (EXISTS(SELECT 1 FROM public.cards c WHERE c.id=_card_id AND c.board_id=b.id) OR EXISTS(SELECT 1 FROM public.card_mirrors m WHERE m.card_id=_card_id AND NOT m.archived AND m.board_id=b.id)) $$;
CREATE OR REPLACE FUNCTION public.accept_board_invite(_token uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE inv public.board_invites; uid uuid:=auth.uid(); verified_email text; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Sign in to accept this invitation'; END IF; SELECT email INTO verified_email FROM auth.users WHERE id=uid AND email_confirmed_at IS NOT NULL; SELECT * INTO inv FROM public.board_invites WHERE token=_token AND accepted_at IS NULL AND expires_at>now() FOR UPDATE; IF inv.id IS NULL OR verified_email IS NULL OR lower(inv.email)<>lower(verified_email) THEN RAISE EXCEPTION 'Invitation is expired, already accepted, or belongs to a different email address'; END IF; INSERT INTO public.board_members(board_id,user_id) VALUES(inv.board_id,uid) ON CONFLICT DO NOTHING; UPDATE public.board_invites SET accepted_at=now() WHERE id=inv.id; RETURN inv.board_id; END $$;
CREATE OR REPLACE FUNCTION public.card_destination(_card_id uuid,_board_id uuid,_list_id uuid,_index integer,_mode text,_title text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.cards; dest uuid; pos double precision; prevpos double precision; nextpos double precision; cl record; lid uuid; lab record; newlabel uuid; mirrored public.card_mirrors; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT * INTO c FROM public.cards WHERE id=_card_id; IF c.id IS NULL THEN SELECT * INTO mirrored FROM public.card_mirrors WHERE id=_card_id; SELECT * INTO c FROM public.cards WHERE id=mirrored.card_id; END IF; IF c.id IS NULL OR NOT public.can_access_card(c.id) OR NOT public.can_access_board(_board_id) THEN RAISE EXCEPTION 'Card or destination unavailable'; END IF; IF mirrored.id IS NOT NULL AND NOT public.can_access_board(mirrored.board_id) THEN RAISE EXCEPTION 'Mirror unavailable'; END IF; IF NOT EXISTS(SELECT 1 FROM public.lists WHERE id=_list_id AND board_id=_board_id AND NOT archived) THEN RAISE EXCEPTION 'Choose an active destination list'; END IF; IF _mode NOT IN ('move','copy','mirror') THEN RAISE EXCEPTION 'Unknown action'; END IF; IF _mode='mirror' AND NOT public.owns_board(c.board_id) THEN RAISE EXCEPTION 'Only the source board owner can share a mirror'; END IF; IF _mode='move' AND mirrored.id IS NULL AND c.board_id<>_board_id AND NOT public.owns_board(c.board_id) THEN RAISE EXCEPTION 'Only the source board owner can move between boards'; END IF; PERFORM pg_advisory_xact_lock(hashtext(_list_id::text)); IF _index<0 THEN RAISE EXCEPTION 'Invalid position'; END IF; SELECT position INTO prevpos FROM (SELECT id,position FROM public.cards WHERE list_id=_list_id AND NOT archived UNION ALL SELECT id,position FROM public.card_mirrors WHERE list_id=_list_id AND NOT archived) x WHERE NOT(_mode='move' AND id=_card_id) ORDER BY position,id OFFSET greatest(_index-1,0) LIMIT 1; IF _index=0 THEN prevpos:=NULL; END IF; SELECT position INTO nextpos FROM (SELECT id,position FROM public.cards WHERE list_id=_list_id AND NOT archived UNION ALL SELECT id,position FROM public.card_mirrors WHERE list_id=_list_id AND NOT archived) x WHERE NOT(_mode='move' AND id=_card_id) ORDER BY position,id OFFSET _index LIMIT 1; pos:=CASE WHEN prevpos IS NULL AND nextpos IS NULL THEN 1000 WHEN prevpos IS NULL THEN nextpos-1000 WHEN nextpos IS NULL THEN prevpos+1000 ELSE (prevpos+nextpos)/2 END; IF _mode='mirror' THEN INSERT INTO public.card_mirrors(card_id,board_id,list_id,position) VALUES(c.id,_board_id,_list_id,pos) RETURNING id INTO dest; RETURN dest; END IF; IF _mode='move' THEN IF mirrored.id IS NOT NULL THEN UPDATE public.card_mirrors SET board_id=_board_id,list_id=_list_id,position=pos WHERE id=mirrored.id; RETURN mirrored.id; END IF; UPDATE public.cards SET board_id=_board_id,list_id=_list_id,position=pos WHERE id=c.id; dest:=c.id; ELSE IF NULLIF(trim(_title),'') IS NULL THEN RAISE EXCEPTION 'Card name is required'; END IF; INSERT INTO public.cards(board_id,list_id,title,description,due_date,start_date,is_complete,position,cover_url,claude_enabled,claude_instructions,claude_status,claude_output,claude_last_run_at) VALUES(_board_id,_list_id,trim(_title),c.description,c.due_date,c.start_date,c.is_complete,pos,c.cover_url,c.claude_enabled,c.claude_instructions,c.claude_status,c.claude_output,c.claude_last_run_at) RETURNING id INTO dest; FOR cl IN SELECT * FROM public.checklists WHERE card_id=c.id LOOP INSERT INTO public.checklists(card_id,title,position) VALUES(dest,cl.title,cl.position) RETURNING id INTO lid; INSERT INTO public.checklist_items(checklist_id,text,is_done,position) SELECT lid,text,is_done,position FROM public.checklist_items WHERE checklist_id=cl.id; END LOOP; INSERT INTO public.youtube_details SELECT (jsonb_populate_record(NULL::public.youtube_details,to_jsonb(y)||jsonb_build_object('card_id',dest))).* FROM public.youtube_details y WHERE card_id=c.id; INSERT INTO public.card_members(card_id,user_id) SELECT dest,cm.user_id FROM public.card_members cm WHERE cm.card_id=c.id AND (EXISTS(SELECT 1 FROM public.boards b WHERE b.id=_board_id AND b.owner_id=cm.user_id) OR EXISTS(SELECT 1 FROM public.board_members bm WHERE bm.board_id=_board_id AND bm.user_id=cm.user_id)); END IF; FOR lab IN SELECT l.* FROM public.labels l JOIN public.card_labels x ON x.label_id=l.id WHERE x.card_id=c.id LOOP SELECT id INTO newlabel FROM public.labels WHERE board_id=_board_id AND name=lab.name AND color=lab.color LIMIT 1; IF newlabel IS NULL THEN INSERT INTO public.labels(board_id,name,color) VALUES(_board_id,lab.name,lab.color) RETURNING id INTO newlabel; END IF; INSERT INTO public.card_labels(card_id,label_id) VALUES(dest,newlabel) ON CONFLICT DO NOTHING; END LOOP; IF _mode='move' AND c.board_id<>_board_id THEN DELETE FROM public.card_labels WHERE card_id=dest AND label_id IN (SELECT id FROM public.labels WHERE board_id=c.board_id); END IF; RETURN dest; END $$;
REVOKE ALL ON FUNCTION public.can_access_board(uuid), public.can_access_card(uuid), public.board_people(uuid), public.card_people(uuid), public.accept_board_invite(uuid), public.card_destination(uuid,uuid,uuid,integer,text,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.can_access_board(uuid), public.can_access_card(uuid), public.board_people(uuid), public.card_people(uuid), public.accept_board_invite(uuid), public.card_destination(uuid,uuid,uuid,integer,text,text) TO authenticated,service_role;
ALTER PUBLICATION supabase_realtime ADD TABLE public.card_mirrors, public.card_labels, public.labels, public.checklists, public.checklist_items, public.card_members, public.board_members;